package org.rabochaya.maptests;
import android.content.*;import android.graphics.*;import android.view.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Component colours are exercised in the existing offlineformats scenario, not a new baseline. */
final class KmlComponentStyleChecks {
 final MapAndroidChecks m;final MapLayersChecks layers;final ManagerRotationChecks raw;final ManagerVisualChecks visual;
 KmlComponentStyleChecks(MapAndroidChecks m){this.m=m;layers=new MapLayersChecks(m);raw=new ManagerRotationChecks(m);visual=new ManagerVisualChecks(m);}
 String polygon(String coordinates){return "<Polygon><outerBoundaryIs><LinearRing><coordinates>"+coordinates+"</coordinates></LinearRing></outerBoundaryIs></Polygon>";}
 void pixel(Bitmap image,double lon,double lat,int expected)throws Exception{int x=(int)Math.round(image.getWidth()/2.0+lon/360*2048),y=(int)Math.round(image.getHeight()/2.0-Math.log(Math.tan(Math.PI/4+Math.toRadians(lat)/2))/(2*Math.PI)*2048);int actual=image.getPixel(x,y);m.check(Math.abs(Color.red(actual)-Color.red(expected))<=1&&Math.abs(Color.green(actual)-Color.green(expected))<=1&&Math.abs(Color.blue(actual)-Color.blue(expected))<=1,"component actual renderer pixel "+lon+","+lat+" expected="+Integer.toHexString(expected)+" actual="+Integer.toHexString(actual));}
 void render(Object doc)throws Exception{final Throwable[] failure={null};m.runOnMainSync(()->{Object map=null;Bitmap image=null;try{Class<?> listener=m.owned("LocalMapView$Listener");Object callback=Proxy.newProxyInstance(listener.getClassLoader(),new Class[]{listener},(o,method,args)->null);map=m.owned("LocalMapView").getConstructor(Context.class,List.class,File.class,listener).newInstance(m.getTargetContext(),m.call(doc,"features",new Class[]{boolean.class},false),null,callback);View view=(View)map;view.layout(0,0,800,600);m.call(map,"restore",new Class[]{double.class,double.class,double.class},.5,.5,3.0);Field ready=map.getClass().getDeclaredField("mapReady");ready.setAccessible(true);ready.setBoolean(map,false);image=Bitmap.createBitmap(800,600,Bitmap.Config.ARGB_8888);view.draw(new Canvas(image));pixel(image,-20,20,0xff00ff00);pixel(image,-10,-10,0xff0000ff);pixel(image,15,-15,0xff921710);pixel(image,-15,7,0xff253020);pixel(image,-25,7,0xff253020);pixel(image,20,20,0xff253020);pixel(image,5,-15,0xff0000ff);}catch(Throwable e){failure[0]=e;}finally{if(image!=null)image.recycle();if(map!=null)try{m.call(map,"close",new Class[]{});}catch(Exception e){failure[0]=e;}}});if(failure[0]!=null)throw new AssertionError(failure[0]);}
 void run()throws Exception{Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());long id=-1,other=-1;int requests=m.requests.get();try{String xml="<kml xmlns='http://www.opengis.net/kml/2.2'><Document><Style id='shared'><IconStyle><color>ff00ff00</color></IconStyle><LineStyle><color>ffff0000</color></LineStyle><PolyStyle><color>800000ff</color><fill>1</fill><outline>1</outline></PolyStyle><LabelStyle><color>ff00ffff</color></LabelStyle></Style><StyleMap id='normal'><Pair><key>normal</key><styleUrl>#shared</styleUrl></Pair></StyleMap><Placemark id='mixed'><name>Компоненты KML</name><styleUrl>#normal</styleUrl><MultiGeometry><Point><coordinates>-20,20</coordinates></Point><LineString><coordinates>-20,-10 0,-10</coordinates></LineString>"+polygon("5,-5 25,-5 25,-25 5,-25 5,-5")+"</MultiGeometry></Placemark><Placemark id='hidden'><name>Прозрачный</name><styleUrl>#normal</styleUrl><Style><IconStyle><color>0000ff00</color></IconStyle><LabelStyle><color>0000ffff</color></LabelStyle><PolyStyle><fill>0</fill><outline>0</outline></PolyStyle></Style><MultiGeometry><Point><coordinates>20,20</coordinates></Point>"+polygon("-25,0 -5,0 -5,15 -25,15 -25,0")+"</MultiGeometry></Placemark></Document></kml>";Object doc=m.codec.getMethod("parse",byte[].class).invoke(null,(Object)xml.getBytes("UTF-8"));m.assets(doc).put("attachments/style-keep.bin",new byte[]{8,7,6,5});id=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,"QA_COMPONENT_STYLE");other=new GeometryConfirmationChecks(m).fixture(store,false);byte[] before=raw.xml(raw.load(store,id)),otherXml=raw.xml(raw.load(store,other));Map<String,byte[]> assets=new HashMap<>(m.assets(raw.load(store,id))),otherAssets=new HashMap<>(m.assets(raw.load(store,other)));doc=raw.load(store,id);render(doc);m.check(Arrays.equals(before,raw.xml(doc)),"renderer does not rewrite KML component/shared styles");ByteArrayOutputStream kmz=new ByteArrayOutputStream();m.call(doc,"kmz",new Class[]{OutputStream.class},kmz);Object round=m.codec.getMethod("read",InputStream.class,boolean.class).invoke(null,new ByteArrayInputStream(kmz.toByteArray()),true);render(round);m.check(Arrays.equals(before,raw.xml(round)),"KML styles/flags/DOM exact through KMZ roundtrip");m.check(Arrays.equals(assets.get("attachments/style-keep.bin"),m.assets(round).get("attachments/style-keep.bin")),"KMZ attachment exact");layers.main(id);m.setViewport(.5,.5,3);Thread.sleep(2000);m.capture("mvisual-kml-components");visual.finish();layers.main(id);m.setViewport(.5,.5,3);Thread.sleep(2000);m.capture("mvisual-kml-components-reopen");layers.unchanged(store,id,before,assets);layers.unchanged(store,other,otherXml,otherAssets);m.check(m.requests.get()==requests,"component styles do not send object/attachment or tile requests");visual.emit("KML_COMPONENT_STYLE renderer/StyleMap/inline/alpha/fill/outline/KMZ/reopen/data PASS");}finally{visual.finish();for(long project:new long[]{id,other})if(project>0){m.call(store,"remove",new Class[]{long.class},project);m.staticCall("LocalMapActivity","cleanupDeletedProject",new Class[]{Context.class,long.class},m.getTargetContext(),project);}m.call(store,"close",new Class[]{});}}
}
